import org.junit.jupiter.api.Test;

/**
 * Tests of MenuOptionRouting (legacy PAGOMNU, paragraph 2000-ELEGIR-OPCION, lines 43-55).
 * Pins RULE-006.
 *
 * Legacy branches of the EVALUATE OPCIONI:
 *   WHEN '1'  -> XCTL PROGRAM('PAGOORD')
 *   WHEN '9'  -> PERFORM 9000-TERMINAR (sends WS-FIN = 'SESION TERMINADA', PIC X(20))
 *   OTHER     -> MENSAJEO = 'OPCION NO VALIDA'
 */
class MenuOptionRoutingServiceTest {

    private final MenuOptionRoutingService service = new MenuOptionRoutingService();

    private MenuOptionRoutingResponse run(String option) {
        return service.execute(new MenuOptionRoutingRequest(option));
    }

    private void assertInvalidOption(String option) {
        assertThatThrownBy(() -> run(option))
                .isInstanceOf(BusinessError.class)
                .satisfies(t -> {
                    BusinessError e = (BusinessError) t;
                    assertThat(e.legacyCode()).isEqualTo("OPCION NO VALIDA");
                    assertThat(e.code()).isEqualTo("INVALID_OPTION");
                });
    }

    // RULE-006 scenario: User selects payment order entry (WHEN '1' -> XCTL PAGOORD)
    @Test
    void user_selects_payment_order_entry() {
        MenuOptionRoutingResponse response = run("1");

        assertThat(response).isNotNull();
        assertThat(response.destination()).isEqualTo("PAGOORD");
    }

    // RULE-006 scenario: User exits (WHEN '9' -> 9000-TERMINAR, text 'SESION TERMINADA')
    @Test
    void user_exits() {
        MenuOptionRoutingResponse response = run("9");

        assertThat(response).isNotNull();
        assertThat(response.destination()).isNotNull();
        assertThat(response.destination().trim()).isEqualTo("SESION TERMINADA");
        assertThat(response.destination()).isNotEqualTo("PAGOORD");
    }

    // RULE-006 scenario: Invalid option '5' (WHEN OTHER)
    @Test
    void invalid_option() {
        assertInvalidOption("5");
    }

    // RULE-006 WHEN OTHER: every other digit is rejected
    @Test
    void invalid_option_zero() {
        assertInvalidOption("0");
    }

    @Test
    void invalid_option_two() {
        assertInvalidOption("2");
    }

    @Test
    void invalid_option_eight() {
        assertInvalidOption("8");
    }

    // RULE-006 WHEN OTHER: letters are not '1' nor '9'
    @Test
    void invalid_option_letter() {
        assertInvalidOption("A");
    }

    // RULE-006 WHEN OTHER: the comparison is exact, lowercase letters are rejected too
    @Test
    void invalid_option_lowercase_letter() {
        assertInvalidOption("a");
    }

    // RULE-006 WHEN OTHER: blank map field (space) is not '1' nor '9'
    @Test
    void invalid_option_blank() {
        assertInvalidOption(" ");
    }

    // RULE-006 WHEN OTHER: empty field is neither '1' nor '9'
    @Test
    void invalid_option_empty() {
        assertInvalidOption("");
    }

    // RULE-006 WHEN OTHER: absent option is neither '1' nor '9'
    @Test
    void invalid_option_null() {
        assertInvalidOption(null);
    }

    // RULE-006 WHEN OTHER: more than one character is not equal to '1'
    @Test
    void invalid_option_two_characters_starting_with_one() {
        assertInvalidOption("11");
    }

    // RULE-006 WHEN OTHER: more than one character is not equal to '9'
    @Test
    void invalid_option_two_characters_starting_with_nine() {
        assertInvalidOption("91");
    }

    // RULE-006: a rejection does not affect later valid options (no state kept between calls)
    @Test
    void valid_option_after_invalid_option_is_still_routed() {
        assertInvalidOption("5");

        MenuOptionRoutingResponse response = run("1");

        assertThat(response.destination()).isEqualTo("PAGOORD");
    }
}
